/**
 * Label resolution for the layout-builder elements that render a heading of
 * their own (SSE-39).
 *
 * `AutoAccountingSection` and the PO-tables tab printed a hard-coded
 * `$t('auto_accounting')` / `$t('po_tables')`, so the `translation_key` and the
 * renamed `label` the layout builder writes into the element were both ignored:
 * an admin could rename the element and see no effect at all.
 *
 * Resolution order, in the order an admin expects it to win:
 *   1. `translation_key` — the only label that follows the viewer's locale, so
 *      it beats a single static string. A key with no translation behind it is
 *      skipped: the palette seeds keys (`section_auto_accounting`,
 *      `po_panel_tables`) that do not exist in Tolgee, and echoing the raw key
 *      into the UI would be worse than the bundled default.
 *   2. a renamed `title` / `label` / `text` — the layout builder writes the new
 *      name into all three. The placeholder `'Label'` the palette seeds, and
 *      the palette's own English `text`, are NOT renames: taking those would
 *      pin every locale to English for layouts nobody ever edited.
 *   3. the element's bundled translation key, i.e. today's behaviour.
 */

/** The placeholder the element palette seeds into `label`. */
const PLACEHOLDER_LABEL = 'label';

export interface ElementLabelOptions {
  /** Bundled key used when nothing is configured, e.g. `auto_accounting`. */
  fallbackKey: string;
  /** The palette's default `text` for this element, e.g. `Auto Accounting`. */
  defaultText?: string;
}

/** `i18n.t` echoes the key back when nothing matched — so must a stub. */
export type TranslateFn = (key: string) => string;

function getRenamedText(
  field: Record<string, unknown> | null | undefined,
  defaultText: string,
): string {
  for (const value of [field?.title, field?.label, field?.text]) {
    if (typeof value !== 'string') {
      continue;
    }
    const trimmed = value.trim();
    if (!trimmed || trimmed.toLowerCase() === PLACEHOLDER_LABEL) {
      continue;
    }
    if (defaultText && trimmed === defaultText) {
      continue;
    }
    return trimmed;
  }
  return '';
}

export function getConfiguredElementLabel(
  field: Record<string, unknown> | null | undefined,
  translate: TranslateFn,
  { fallbackKey, defaultText = '' }: ElementLabelOptions,
): string {
  const translation_key =
    typeof field?.translation_key === 'string' ? field.translation_key.trim() : '';

  if (translation_key) {
    const translation = translate(translation_key);
    if (translation && translation !== translation_key) {
      return translation;
    }
  }

  const renamed = getRenamedText(field, defaultText);
  if (renamed) {
    return renamed;
  }

  return translate(fallbackKey);
}
